from fractions import Fraction


def expected_turns(n: int, m: int, jumps: list[list[int]]) -> list[int] | None:
    jump = {a: b for a, b in jumps}

    def resolve(x: int) -> int:
        while x in jump:
            x = jump[x]
        return x

    def succ(p: int) -> list[int]:
        res = []
        for r in range(1, m + 1):
            q = p + r if p + r <= n else 2 * n - p - r
            res.append(resolve(q))
        return res

    start = resolve(0)
    if start == n:
        return [0, 1]

    # Explore states reachable from the start (cells in 0..n-1 after jumps).
    succs = {}
    seen = {start}
    stack = [start]
    while stack:
        p = stack.pop()
        s = succ(p)
        succs[p] = s
        for q in s:
            if q != n and q not in seen:
                seen.add(q)
                stack.append(q)

    # States that can reach the finish. If any reachable state cannot,
    # the game may never end with positive probability.
    good = {n}
    changed = True
    while changed:
        changed = False
        for p in succs:
            if p not in good and any(q in good for q in succs[p]):
                good.add(p)
                changed = True
    if any(p not in good for p in succs):
        return None

    # Solve E[p] - (1/m) * sum E[q] = 1 over reachable non-terminal states.
    states = sorted(seen)
    idx = {p: i for i, p in enumerate(states)}
    k = len(states)
    A = [[Fraction(0)] * (k + 1) for _ in range(k)]
    for p in states:
        i = idx[p]
        A[i][i] += 1
        for q in succs[p]:
            if q != n:
                A[i][idx[q]] -= Fraction(1, m)
        A[i][k] = Fraction(1)

    # Gauss-Jordan elimination with exact fractions.
    for col in range(k):
        pivot = None
        for r in range(col, k):
            if A[r][col] != 0:
                pivot = r
                break
        if pivot is None:
            return None
        A[col], A[pivot] = A[pivot], A[col]
        inv = 1 / A[col][col]
        A[col] = [v * inv for v in A[col]]
        for r in range(k):
            if r != col and A[r][col] != 0:
                factor = A[r][col]
                A[r] = [a - factor * b for a, b in zip(A[r], A[col])]

    ans = A[idx[start]][k]
    return [ans.numerator, ans.denominator]
